async function renderTerms(){var e=activeTrackForPath(window.location.pathname);e&&await loadTrackContent(e.examType);var t=e?trackCompliance(e.examType):{orgLine:HUB_FOOTER_ORG_LINE,termsParagraph2:HUB_TERMS_PARAGRAPH2};appEl.innerHTML='<div class="narrow-page static-doc"><h1>Terms of Use</h1><p class="muted">PassExamHQ provides original, independently-authored practice questions for exam preparation purposes only. It is not affiliated with, authorized by, sponsored by, or endorsed by '+t.orgLine+" or any other government agency. All official state trademarks, examination names, and statutory references are used purely for identification and descriptive purposes. Access codes are non-transferable and grant access to one exam track as specified at purchase. We make no guarantee of passing any official exam.</p>"+t.termsParagraph2+'<p class="muted">Referral points have no cash value and cannot be redeemed, exchanged, or refunded for cash or any other payment method — they may only be applied toward a course through this site. Points may expire or be adjusted, and the referral program itself may be modified, suspended, or discontinued, at any time. We reserve the right to revoke points or access obtained through fraud, abuse, or violation of these terms.</p><p class="muted">Only one promotional discount or code may be applied per purchase — discounts cannot be combined or stacked with each other, though referral points may still be applied on top of a single active discount. Some promotions are restricted to first-time buyers and will be rejected at checkout for an email already associated with a prior purchase.</p><button class="btn-secondary btn-sm" data-act="go-back">← Back</button></div>'}function renderPrivacy(){var e=function(e,t){return'<a href="'+e+'" target="_blank" rel="noopener noreferrer">'+t+"</a>"};appEl.innerHTML='<div class="narrow-page static-doc"><h1>Privacy</h1><p class="muted">Last updated: September 18, 2026</p><h2>What we collect</h2><p class="muted"><strong>Your account and study progress.</strong> Your access code and its status, the tracks or topics you\'ve bought, your quiz, exam and study-resource progress, your settings (theme, font size, quiz options), and an exam date if you choose to add one.</p><p class="muted"><strong>Information you give us.</strong> Your email address, and anything else you type in, when you:</p><ul class="muted"><li>buy a track (to send your receipt and access code)</li><li>enter your email at checkout, even if you don\'t finish buying (we may send you a reminder)</li><li>ask for a reminder, join a waitlist for your state, or verify a promo code</li><li>ask us to email you a link to free practice questions (and, only if you tick the box for them, occasional study tips and offers, each with a way to unsubscribe)</li><li>join the referral program, refer a friend, or send a gift (we use your friend\'s name and email only to send the invitation or gift and to credit referral points)</li><li>submit a refund claim, issue report, suggestion, or testimonial</li></ul><p class="muted"><strong>How you use the site.</strong> When you visit, we record a random visitor ID kept in your browser, the pages you view, how long you stay, how many times you click, the site or ad that sent you (including ad campaign details and Google\'s click ID), your IP address and the approximate location it indicates (country, region, city), and your device and browser type. To protect the site, we also log blocked attempts to reach content without access, including the IP address.</p><h2>Cookies and browser storage</h2><p class="muted">We set one cookie, <code>pxq_state</code>, which remembers your state (from your approximate location, or the state you pick) so we show the right exam content. It lasts one year. We also keep your settings, your visitor ID, and any referral or partner code in your browser\'s local storage. Google and Microsoft Clarity set their own cookies, described below.</p><h2>Services we use</h2><ul class="muted"><li><strong>Stripe</strong> processes payments. We never see or store your card details.</li><li><strong>Cloudflare</strong> hosts the site, protects it from abuse (including the Turnstile check at checkout and on some forms), and provides basic traffic analytics.</li><li><strong>Resend</strong> delivers our emails.</li><li><strong>Google Ads</strong> tells us whether our ads lead to purchases, and may show our ads to people who have visited this site when they later use Google or its partner sites and apps (remarketing). Google uses cookies and similar technologies to do this. You can turn off personalized ads in '+e("https://myadcenter.google.com/","My Ad Center")+", and read "+e("https://policies.google.com/technologies/partner-sites","how Google uses information from sites that use its services")+".</li><li><strong>Microsoft Clarity</strong> records how visitors interact with pages (clicks, scrolling, mouse movement) so we can see what's confusing and improve the site. See the "+e("https://privacy.microsoft.com/privacystatement","Microsoft Privacy Statement")+'.</li></ul><h2>How we use it</h2><p class="muted">To give you access to what you bought, save your progress, send the emails described above (including study reminders and tips related to your purchase), understand and improve the site, measure our advertising, and prevent fraud and abuse.</p><h2>What we don\'t do</h2><p class="muted">We don\'t sell your personal information. We share it only with the services above, as needed to run the site and our advertising.</p><h2>Your choices</h2><p class="muted">You can block or clear cookies in your browser, turn off personalized ads through Google, or <a href="#/contact">contact us</a> to see or delete the information we hold about you, or to stop non-essential emails.</p><button class="btn-secondary btn-sm" data-act="go-back">← Back</button></div>'}function renderAbout(){appEl.innerHTML='<div class="narrow-page static-doc"><h1>About PassExamHQ</h1><p class="muted">PassExamHQ builds independent practice question banks for state and national licensing exams — driver\'s license and CDL knowledge tests, motorcycle endorsements, notary public exams, real estate licensing, boating safety, and more — each one built directly from the current official handbook or manual for that specific state and track, not a generic national bank reused everywhere.</p><p class="muted">Every track is a single one-time purchase, not a subscription: pay once, keep access. That access includes the full question bank for unlimited practice, timed mock exams that mirror the real format, voice-enabled answering and read-aloud, and per-topic progress tracking so you know what to actually restudy before test day — not just an overall score.</p><p class="muted">We back every track with a pass-or-money-back guarantee (see the full <a href="#/guarantee">guarantee terms</a>), and our results page shows real, unedited numbers pulled straight from our own database, not invented marketing figures.</p><p class="muted">PassExamHQ is an independent study tool. We are not affiliated with, authorized by, sponsored by, or endorsed by any state department of motor vehicles, state licensing agency, or official examination vendor, and completing our practice questions or mock exams does not register you for, or substitute for, any official state or federal exam.</p><button class="btn-secondary btn-sm" data-act="go-back">← Back</button></div>'}var FAQ_CATEGORIES=[{category:"Getting Started",items:[{q:"What is PassExamHQ?",a:function(){return'Independent practice question banks for state and national licensing exams, built directly from official handbooks for each specific state and track. See the full <a href="#/about">About page</a>.'}},{q:"Which states and exams do you cover?",a:function(){return'<a href="'+tracksHomeHref()+"\">Browse all tracks</a> to see what's currently live for your state."}},{q:"Can I try questions before buying?",a:function(){return'Yes — every track has free sample questions, no account needed. Open any track from the <a href="'+tracksHomeHref()+'">tracks page</a> to try one.'}},{q:"Do I need to create an account?",a:function(){return'No separate signup. Your access code (emailed after purchase or redemption) is your entire login — see "How do I redeem my code?" below.'}}]},{category:"Buying & Pricing",items:[{q:"How much does a track cost, and is it a subscription?",a:function(){return'Each track is a single one-time payment, not a subscription — pay once and keep access for good. Prices vary by track; <a href="'+tracksHomeHref()+'">browse tracks</a> to see the current price for yours.'}},{q:"What payment methods do you accept?",a:function(){return"Card, Apple Pay, or Google Pay — checkout runs through Stripe, and whichever wallet your device supports shows up automatically."}},{q:"Do you offer discounts or promo codes?",a:function(){return"When a discount is active it shows right on the buy page. Some discounts need a code (enter it in the promo field and click Apply); others auto-apply for a qualifying email domain (e.g. a student discount for a .edu address) with no code needed."}},{q:"Can I buy a track as a gift?",a:function(){return"Yes — <a href=\"#/gift\">gift a track</a>. You can enter the recipient's email and we'll send their code directly, or leave it blank and get a shareable code to send yourself."}}]},{category:"Your Access Code",items:[{q:"How do I redeem my code?",a:function(){return'Go to <a href="#/redeem">Redeem code</a> and enter it exactly as emailed. That logs you in on this device — no password to create or remember.'}},{q:"Do I need a password?",a:function(){return"No. Your code is the entire login mechanism, by design — one thing to keep track of, not a code and a password."}},{q:"Can I use my code on more than one device?",a:function(){return'Yes — re-enter the same code on another device\'s <a href="#/redeem">Redeem code</a> page and it logs that device into the same account.'}},{q:"I lost my code, or never received the email — what now?",a:function(){return'<a href="#/contact">Contact us</a> with the email you purchased or were gifted with, and we\'ll help track it down.'}}]},{category:"Studying & Practice",items:[{q:"What's included once I unlock a track?",a:function(){return'The full question bank for unlimited practice, a timed mock exam plus a "Weak Spots" drill of the hardest questions, voice-enabled answering and read-aloud, a study resource library, and per-topic progress tracking.'}},{q:"Can questions be read aloud to me?",a:function(){return"Yes — voice-enabled practice can read each question aloud, and you can answer by voice too, right from the practice quiz."}},{q:"Can I practice by difficulty level?",a:function(){return'Yes — the practice quiz has an Easy / Moderate / Hard / Extremely Hard filter, plus "All," so you can drill weak spots specifically.'}},{q:"How many questions are on my exam, and how long is it?",a:function(){return"This varies a lot by track — open your specific track's page (from the <a href=\""+tracksHomeHref()+'">tracks list</a>) for its exact question count, time limit, and passing score.'}}]},{category:"Progress Tracking",items:[{q:"How do I know if I'm ready for the real exam?",a:function(){return"Once you're logged in, the Progress tab shows Accuracy (how often you're getting questions right) and Coverage (how much of the bank you've actually practiced) broken down per topic — so you know exactly what to restudy, not just an overall score."}}]},{category:"Guarantee & Refunds",items:[{q:"What if I take the real exam and don't pass?",a:function(){return'We refund <span class="js-refund-pct">'+refundFailurePercent+'</span>% of your purchase, as long as you maintained at least <span class="js-accuracy-pct">'+progressAccuracyPassPct+'</span>% Accuracy and <span class="js-coverage-pct">'+progressCoveragePassPct+'</span>% Coverage on the Progress tab. Full details on the <a href="#/guarantee">guarantee page</a>.'}},{q:"Can I get a refund if I just change my mind?",a:function(){return"Yes — a 7-day, no-questions-asked refund covers that separately from the pass-guarantee above."}},{q:"How do I request a refund?",a:function(){return'Start a <a href="#/refund">refund request</a> here.'}}]},{category:"Referrals, Points & Gifts",items:[{q:"How does referring friends work?",a:function(){return'Refer friends and earn points toward free access — find your track\'s "Refer & earn" link from its <a href="'+tracksHomeHref()+'">track page</a>.'}},{q:"How do I check my referral points?",a:function(){return'On the buy page, click "Check my points" — you can apply them toward that purchase\'s total right there.'}}]},{category:"Account & Legal",items:[{q:"What data do you store about me?",a:function(){return'See exactly what and why on our <a href="#/privacy">privacy page</a>.'}},{q:"Where are your terms of service?",a:function(){return'<a href="#/terms">Terms of service</a>.'}},{q:"My question isn't answered here",a:function(){return'<a href="#/contact">Contact us</a> and we\'ll reply to your email.'}}]}];function refreshFaqDynamicSpans(){loadSiteConfig().then(function(){document.querySelectorAll(".js-refund-pct").forEach(function(e){e.textContent=refundFailurePercent}),document.querySelectorAll(".js-accuracy-pct").forEach(function(e){e.textContent=progressAccuracyPassPct}),document.querySelectorAll(".js-coverage-pct").forEach(function(e){e.textContent=progressCoveragePassPct})})}function renderFaq(){appEl.innerHTML='<div class="narrow-page static-doc"><h1>Frequently Asked Questions</h1><p class="muted">Quick answers on buying, your access code, studying, and the guarantee. Still stuck? <a href="#/contact">Contact us</a> or use the chat bubble in the corner.</p>'+FAQ_CATEGORIES.map(function(e){return'<section class="faq-category"><h2>'+escapeHtml(e.category)+"</h2>"+e.items.map(function(e){return'<details class="faq-item"><summary>'+escapeHtml(e.q)+'</summary><div class="faq-answer muted">'+e.a()+"</div></details>"}).join("")+"</section>"}).join("")+'<button class="btn-secondary btn-sm" data-act="go-back">← Back</button></div>',refreshFaqDynamicSpans();var e=[];FAQ_CATEGORIES.forEach(function(t){t.items.forEach(function(t){e.push({"@type":"Question",name:t.q,acceptedAnswer:{"@type":"Answer",text:stripHtml(t.a())}})})}),injectJsonLd("faq-jsonld",{"@context":"https://schema.org","@type":"FAQPage",mainEntity:e})}function blogDate(e){if(null==e||""===e)return null;var t="number"==typeof e?new Date(e<1e12?1e3*e:e):new Date(e);return isNaN(t.getTime())?null:t}function blogListHref(e,t){var a=[];return e&&a.push("kind="+encodeURIComponent(e)),void 0!==t&&a.push("state="+encodeURIComponent(t)),"/blog"+(a.length?"?"+a.join("&"):"")}function blogListItemsHtml(e,t,a){return e.length?'<div class="blog-list">'+e.map(function(e){var s=kindFromSlug(e.kind)||e.kind,o=blogPostHref(e.slug,t,a);return'<article class="blog-list-item card'+(e.featured?" blog-list-item-featured":"")+'">'+(e.featured?'<span class="badge blog-list-item-featured-badge">🎯 Practice Test Guide</span>':"")+'<span class="badge blog-list-item-badge">'+escapeHtml(s)+"</span>"+(INTL_STUDENTS_ARTICLE_SLUGS[e.kind]===e.slug?internationalBadgeHtml():"")+'<h2><a href="'+o+'">'+escapeHtml(e.title)+'</a></h2><p class="muted blog-list-meta">'+(e.state_code?escapeHtml(e.state_code)+" · ":"")+(blogDate(e.published_at)?blogDate(e.published_at).toLocaleDateString():"")+'</p><p class="blog-list-excerpt">'+escapeHtml(e.excerpt)+'</p><a class="blog-read-more" href="'+o+'">Read more →</a></article>'}).join("")+"</div>":'<p class="muted">No articles in this category yet — check back soon.</p>'}function blogCategoryTabsHtml(e,t){var a={};e.forEach(function(e){a[e.kind]=(a[e.kind]||0)+1});var s=[];for(var o in HUB_KIND_SLUGS)a[HUB_KIND_SLUGS[o]]&&s.push(HUB_KIND_SLUGS[o]);return s.length<2?"":'<div class="blog-category-tabs" role="tablist"><a class="'+(t?"":"active")+'" href="'+blogListHref("")+'">All ('+e.length+")</a>"+s.map(function(e){return'<a class="'+(e===t?"active":"")+'" href="'+blogListHref(e)+'">'+escapeHtml(kindFromSlug(e)||e)+" ("+a[e]+")</a>"}).join("")+"</div>"}function blogStateFilterHtml(e,t,a,s){var o={},r=0;e.forEach(function(e){e.state_code?o[e.state_code]=(o[e.state_code]||0)+1:r++});var n=Object.keys(o).sort(function(e,t){return(STATE_LABELS[e]||e).localeCompare(STATE_LABELS[t]||t)});if(!n.length)return"";var i=['<option value="">All states ('+e.length+")</option>"].concat(n.map(function(e){return'<option value="'+e+'"'+(e===a?" selected":"")+">"+escapeHtml(STATE_LABELS[e]||e)+" ("+(o[e]+r)+")</option>"}));return(s&&a?'<p class="muted blog-state-defaulted-note">📍 Showing '+escapeHtml(STATE_LABELS[a]||a)+' (based on your saved state) — <a href="'+blogListHref(t,"")+'">view all states</a></p>':"")+'<select class="blog-state-filter" data-act="change-blog-state-filter" data-kind="'+escapeHtml(t)+'" aria-label="Filter by state">'+i.join("")+"</select>"}function drawBlogList(){var e=blogListState.posts,t=blogListState.postsForKind,a=blogListState.shown,s=blogListState.activeKind,o=blogListState.activeState,r=blogListState.visibleCount,n=a.length-r;appEl.innerHTML='<div class="blog-page"><h1>Guides &amp; Tips</h1><p class="muted">Guides and tips for passing your licensing exam.</p>'+blogCategoryTabsHtml(e,s)+blogStateFilterHtml(t,s,o,blogListState.isDefaulted)+blogListItemsHtml(a.slice(0,r),s,o)+(n>0?'<div class="blog-load-more-wrap"><button class="btn-secondary" data-act="blog-load-more">Load more ('+n+" remaining)</button></div>":"")+'<button class="btn-secondary btn-sm blog-back-btn" data-act="go-back">← Back</button></div>'}function renderBlogList(){var e=new URLSearchParams(location.search),t=e.get("kind")||"",a=e.get("state");appEl.innerHTML='<div class="blog-page"><h1>Guides &amp; Tips</h1><p class="muted">Guides and tips for passing your licensing exam.</p>'+loadingSkeletonHtml(8)+"</div>",apiFetch("/blog").then(function(e){var s=e&&e.posts||[],o=t?s.filter(function(e){return e.kind===t}):s,r=!1,n=a;if(null===n){var i=getStateCookie(),c=i&&o.some(function(e){return e.state_code===i});n=c?i:"",r=!!c}var l=n?o.filter(function(e){return!e.state_code||e.state_code===n}):o;blogListState={posts:s,postsForKind:o,shown:l,activeKind:t,activeState:n,isDefaulted:r,visibleCount:Math.min(BLOG_PAGE_SIZE,l.length)},drawBlogList()}).catch(function(){appEl.innerHTML='<div class="blog-page"><h1>Guides &amp; Tips</h1><p class="muted">Couldn\'t load articles right now.</p></div>'})}function renderBlogPost(e){var t=new URLSearchParams(location.search),a=t.get("from")||"",s=t.get("fromState")||"";appEl.innerHTML='<div class="narrow-page">'+loadingSkeletonHtml(6)+"</div>",Promise.all([apiFetch("/blog/"+encodeURIComponent(e)),apiFetch("/blog").catch(function(){return{posts:[]}})]).then(function(t){var o=t[0]&&t[0].post;if(o){var r=kindFromSlug(o.kind)||o.kind,n="/"+o.kind,i=t[1].posts||[],c=i.findIndex(function(t){return t.slug===e}),l=c>0?i[c-1]:null,d=-1!==c&&c<i.length-1?i[c+1]:null,u=l||d?'<div class="blog-post-prevnext">'+(l?'<a class="blog-post-prevnext-link" href="'+blogPostHref(l.slug,a,s)+'"><span class="muted blog-post-prevnext-label">← Previous</span><span class="blog-post-prevnext-title">'+escapeHtml(l.title)+"</span></a>":"<span></span>")+(d?'<a class="blog-post-prevnext-link blog-post-prevnext-next" href="'+blogPostHref(d.slug,a,s)+'"><span class="muted blog-post-prevnext-label">Next →</span><span class="blog-post-prevnext-title">'+escapeHtml(d.title)+"</span></a>":"<span></span>")+"</div>":"",p=Math.max(1,Math.round(stripHtml(o.body_html).split(/\s+/).length/200));appEl.innerHTML='<div class="narrow-page blog-post'+(o.featured?" blog-post-featured":"")+'"><p class="muted blog-post-back"><a href="'+blogListHref(a,s)+'">← Guides &amp; Tips</a></p>'+(o.featured?'<div class="blog-post-featured-banner">🎯 Practice Test Guide — everything you need for this exam, in one place</div>':"")+'<span class="badge blog-post-badge">'+escapeHtml(r)+"</span>"+(INTL_STUDENTS_ARTICLE_SLUGS[o.kind]===o.slug?internationalBadgeHtml():"")+"<h1>"+escapeHtml(o.title)+'</h1><p class="muted blog-post-meta">'+(o.state_code?escapeHtml(o.state_code)+" · ":"")+(blogDate(o.published_at)?blogDate(o.published_at).toLocaleDateString()+" · ":"")+p+' min read</p><div class="blog-post-body">'+o.body_html+'</div><div class="blog-post-cta-box"><p>Ready to put this into practice?</p><a class="btn-primary" href="'+n+'">Practice '+escapeHtml(r)+" questions →</a></div>"+u+"</div>",injectJsonLd("blog-post-jsonld",{"@context":"https://schema.org","@type":"Article",headline:o.title,description:o.seo_description||o.excerpt,datePublished:blogDate(o.published_at)?blogDate(o.published_at).toISOString():void 0})}else appEl.innerHTML='<div class="narrow-page"><h1>Not found</h1><p class="muted">This article doesn\'t exist or isn\'t published.</p><a href="'+blogListHref(a,s)+'">← Back to Guides &amp; Tips</a></div>'}).catch(function(e){console.error("blog post render failed",e),appEl.innerHTML='<div class="narrow-page"><h1>Could not load this article</h1><p class="muted">Something went wrong loading it — please try again shortly.</p><a href="/blog">← Back to Guides &amp; Tips</a></div>'})}function renderContact(){appEl.innerHTML='<div class="narrow-page"><h1>Contact Us</h1><p class="muted">Questions about your account, a purchase, or anything else — send us a note and we\'ll reply to your email.</p><form data-act="contact-submit" class="card"><label class="muted buy-email-label">Your name (optional)</label><input type="text" name="name" placeholder="Jane Doe"><label class="muted buy-email-label refund-field-spacing">Your email</label><input type="email" name="email" placeholder="you@example.com" required><label class="muted buy-email-label refund-field-spacing">Message</label><textarea name="message" rows="5" placeholder="How can we help?" required></textarea><div id="turnstile-container"></div><button class="btn-primary" type="submit">Send message</button></form></div>',renderTurnstileWidget()}function renderGuarantee(){appEl.innerHTML='<div class="narrow-page static-doc"><h1>Our Guarantee</h1>'+loadingSkeletonHtml(6)+"</div>",Promise.all([loadSiteConfig(),apiFetch("/stats/public").catch(function(){return null})]).then(function(e){var t=e[1],a=t&&null!=t.passRate?'<div class="guarantee-stat-divider"></div><p class="guarantee-stat-label">Backed by real practice data</p><p class="muted guarantee-stat-note">'+t.passRate+'% of practice mock exams taken on PassExamHQ end in a passing score. <a href="#/pass-rates">See the real numbers, by category →</a></p>':"";appEl.innerHTML='<div class="guarantee-page"><section class="guarantee-hero"><div class="guarantee-hero-copy"><span class="badge guarantee-hero-badge">🛡️ Two guarantees, in plain language</span><h1>Pass, or get '+refundFailurePercent+"% back.</h1><p class=\"page-intro-text\">We only sell prep we'd stake our reputation on. Practice to the threshold, sit your official exam, and if you still don't pass, you get "+refundFailurePercent+'% of your purchase back. Changed your mind early instead? A 7-day, no-questions-asked refund covers that too.</p><div class="guarantee-hero-cta"><a class="btn-primary hub-hero-btn" href="/#tracks">Browse guaranteed tracks</a><a class="btn-secondary hub-hero-btn" href="#/refund">I need to file a claim</a></div></div><div class="guarantee-hero-stats"><div class="guarantee-stat-card"><div class="guarantee-stat-icon">🛡️</div><div class="guarantee-stat-value">'+refundFailurePercent+'%</div><p class="muted">money back if you meet the practice requirement and still don\'t pass</p>'+a+'</div><div class="guarantee-stat-card"><div class="guarantee-stat-icon">📅</div><div class="guarantee-stat-value">7 Days</div><p class="muted">no-questions-asked refund if you change your mind early — no conditions to meet</p></div></div></section><section class="guarantee-eligibility"><h2>How to qualify</h2><p class="muted page-intro-text">Three simple conditions — they exist so the guarantee protects people who actually did the work.</p><div class="guarantee-steps">'+guaranteeStepHtml(1,"📊","Practice to the threshold","Maintain at least "+progressAccuracyPassPct+"% Accuracy and "+progressCoveragePassPct+"% Coverage in your practice here — a good-faith-effort requirement, not a formality.")+guaranteeStepHtml(2,"🎓","Take your official exam","Sit the real exam through the official testing authority for your track.")+guaranteeStepHtml(3,"📝","Submit your claim","File a refund request with your result — real-money purchases only, since a free or points-redeemed course has no purchase to refund.")+'</div></section><section class="guarantee-faq"><h2>Refund questions</h2><dl class="guarantee-faq-list">'+guaranteeFaqHtml("What exactly do I get back?",refundFailurePercent+"% of what you paid for the track (or a full refund under the separate 7-day guarantee). Free or points-redeemed courses aren't eligible, since no cash was paid.")+guaranteeFaqHtml("How is a refund paid out?","Once your claim is reviewed and approved, it's issued back to your original payment method through Stripe.")+guaranteeFaqHtml("What if I used a promo code or points?","Any points or promo discount applied at checkout only reduces what you paid — the guarantee still covers whatever cash amount you actually paid.")+guaranteeFaqHtml("Which tracks are covered?","Every active licensing-exam track (Notary, Real Estate, Driver, CDL, Motorcycle, Boating, and every other pass/fail state or professional exam) gets both guarantees — the "+refundFailurePercent+"% pass-or-refund guarantee and the 7-day return window. Our scored, composite national exams (ACT, DAT, CLT, OAT) have no pass/fail threshold to fail, so there's no \"fail the real exam\" claim for those — they're still covered by the 7-day return window, just not the pass-or-refund half.")+"</dl></section></div>"})}function guaranteeStepHtml(e,t,a,s){return'<div class="guarantee-step-card"><span class="guarantee-step-num">'+e+'</span><div class="guarantee-step-icon">'+t+"</div><h3>"+a+'</h3><p class="muted">'+s+"</p></div>"}function guaranteeFaqHtml(e,t){return'<div class="guarantee-faq-item"><dt>'+e+'</dt><dd class="muted">'+t+"</dd></div>"}function embedActiveKinds(){var e=[];return HUB_EXAMS.forEach(function(t){t.active&&-1===e.indexOf(t.examKind)&&e.push(t.examKind)}),e.sort(function(e,t){return e.localeCompare(t)})}function embedPickerHtml(){var e=['<option value="">Choose a category…</option>'].concat(embedActiveKinds().map(function(e){return'<option value="'+escapeHtml(e)+'"'+(e===embedPickedKind?" selected":"")+">"+escapeHtml(e)+"</option>"})),t=embedPickedKind?categoryActiveTracks(embedPickedKind):[],a=['<option value="">Choose a state…</option>'].concat(t.slice().sort(function(e,t){return(STATE_LABELS[e.stateCode]||e.stateCode).localeCompare(STATE_LABELS[t.stateCode]||t.stateCode)}).map(function(e){return'<option value="'+e.stateCode+'"'+(e.stateCode===embedPickedState?" selected":"")+">"+escapeHtml(STATE_LABELS[e.stateCode]||e.stateCode)+"</option>"}));return'<div class="card embed-picker"><label class="gift-picker-field">Category<select data-act="pick-embed-kind">'+e.join("")+'</select></label><label class="gift-picker-field">State<select data-act="pick-embed-state"'+(embedPickedKind?"":" disabled")+">"+a.join("")+"</select></label></div>"}function embedResultHtml(){if(!embedPickedKind||!embedPickedState)return"";var e=categoryActiveTracks(embedPickedKind).filter(function(e){return e.stateCode===embedPickedState})[0];if(!e)return"";var t='<iframe src="'+(location.origin+"/embed/qotd?examType="+encodeURIComponent(e.examType))+'" width="380" height="420" style="border:1px solid #ddd;border-radius:12px;max-width:100%;" loading="lazy" title="PassExamHQ Question of the Day"></iframe>';return'<div class="embed-result"><h3>Your embed code</h3><textarea class="embed-snippet-box" readonly rows="3">'+escapeHtml(t)+'</textarea><button class="btn-secondary btn-sm" type="button" data-act="copy-embed-snippet" data-snippet="'+escapeHtml(t)+'">Copy snippet</button><h3>Live preview</h3><div class="embed-preview-frame">'+t+"</div></div>"}function renderEmbedGenerator(){embedPickedKind="",embedPickedState="",appEl.innerHTML='<div class="narrow-page embed-generator-page"><h1>Embed a Question of the Day</h1><p class="muted page-intro-text">Add a real, rotating practice question to your site — a state subreddit, a forum, an agent blog — with a link back to the full question bank. A new question from the real pool shows automatically every day; no upkeep on your end.</p><div id="embed-picker-wrap">'+embedPickerHtml()+'</div><div id="embed-result-wrap">'+embedResultHtml()+"</div></div>"}function renderPassRates(){appEl.innerHTML='<div class="narrow-page static-doc"><h1>Pass Rate Transparency</h1>'+loadingSkeletonHtml(6)+"</div>",Promise.all([apiFetch("/stats/public").catch(function(){return null}),apiFetch("/stats/pass-rates-by-category").catch(function(){return null}),apiFetch("/stats/quiz-accuracy-by-category").catch(function(){return null})]).then(function(e){var t=e[0],a=e[1],s=e[2],o=a&&a.minSampleSize||20,r=s&&s.minSampleSize||20,n=t&&null!=t.passRate?'<div class="pass-rates-overall-card"><div class="pass-rates-overall-value">'+t.passRate+'%</div><p class="muted">of the '+t.examsCompleted.toLocaleString()+" completed practice exams taken on PassExamHQ ended in a passing score ("+t.examsPassed.toLocaleString()+" of "+t.examsCompleted.toLocaleString()+").</p></div>":'<p class="muted">Not enough completed practice exams yet to show a sitewide number.</p>',i=(a&&a.categories||[]).map(function(e){e.categorySlug&&e.categorySlug;var t=null!=e.passRate?"<strong>"+e.passRate+"%</strong>":'<span class="guide-na">Not enough data yet</span>',a=e.attemptCount>=o?e.attemptCount.toLocaleString():'<span class="guide-na">Not met minimum yet</span>';return"<tr><td>"+escapeHtml(e.kind)+"</td><td>"+a+"</td><td>"+t+'</td><td class="guide-table-cta">'+(e.categorySlug?'<a href="/'+e.categorySlug+'">Practice '+escapeHtml(e.kind)+" →</a>":"")+"</td></tr>"}).join(""),c=(s&&s.categories||[]).map(function(e){var t=null!=e.accuracyRate?"<strong>"+e.accuracyRate+"%</strong>":'<span class="guide-na">Not enough data yet</span>',a=e.questionsAnswered>=r?e.questionsAnswered.toLocaleString():'<span class="guide-na">Not met minimum yet</span>';return"<tr><td>"+escapeHtml(e.kind)+"</td><td>"+a+"</td><td>"+t+'</td><td class="guide-table-cta">'+(e.categorySlug?'<a href="/'+e.categorySlug+'">Practice '+escapeHtml(e.kind)+" →</a>":"")+"</td></tr>"}).join(""),l=c?'<h2 class="comparison-heading">Quiz Accuracy By Category</h2><p class="page-intro-text">Not everyone takes a full timed practice exam — plenty of students only ever use quiz mode, answering questions one at a time with instant feedback. This is that same real, live-computed accuracy, separate from the pass-rate table above: it measures how often quiz answers are correct, not whether a full scored exam was passed, so the two numbers aren\'t directly comparable. Categories with too few answered questions show "Not enough data yet" instead of a percentage, for the same reason as above.</p><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>Category</th><th>Questions Answered</th><th>Accuracy</th><th></th></tr></thead><tbody>'+c+"</tbody></table></div>":"",d='<h2 class="comparison-heading">Exam Pass Rate By Category</h2><p class="muted">Categories with fewer than '+o+' completed exams show "Not enough data yet" instead of a percentage — a rate computed from a handful of attempts is too noisy to mean anything, regardless of which way it points. We never hide a real rate just because it looks bad once there\'s enough data behind it.</p><div class="guide-table-wrap"><table class="guide-table"><thead><tr><th>Category</th><th>Completed Exams</th><th>Pass Rate</th><th></th></tr></thead><tbody>'+i+'</tbody></table></div><p class="guide-source-note">Only fully completed (submitted) practice exams count. Each attempt is scored against the passing threshold that applied to it at the time it was taken. See our <a href="#/guarantee">pass-or-refund guarantee</a> for what this backs, or browse per-state exam mechanics on our <a href="/guides/notary-requirements-by-state">requirements-by-state guides</a>.</p>';appEl.innerHTML='<div class="pass-rates-page"><span class="section-eyebrow">Real numbers, not marketing copy</span><h1>Pass Rate Transparency</h1><p class="page-intro-text">Every pass-rate figure on PassExamHQ — here and everywhere else on the site — reflects practice mock exams completed <em>on PassExamHQ itself</em>, computed live from our own database. It is not, and cannot be, a claim about real official exam outcomes: no testing vendor or state licensing board shares that data with prep providers, so any site claiming an official pass rate is estimating or making it up. What you see below is the one number we can actually measure honestly, shown with the real sample sizes behind it.</p>'+n+l+d+"</div>"})}var CHANGELOG_FIELD_LABELS={exam_question_count:"Question count",exam_duration_sec:"Exam duration",pass_percent:"Passing score",min_correct:"Minimum correct"};function changelogValueLabel(e,t){return null==t?"—":"exam_duration_sec"===e?Math.round(Number(t)/60)+" min":"pass_percent"===e?t+"%":t}function renderChangelog(){appEl.innerHTML='<div class="narrow-page static-doc"><h1>Exam Mechanics Changelog</h1>'+loadingSkeletonHtml(8)+"</div>",apiFetch("/changelog").then(function(e){var t=e&&e.items||[],a=t.map(function(e){var t=e.kind&&HUB_KIND_SLUGS[e.kind]&&e.stateCode?"/"+kindSlug(e.kind)+"/"+e.stateCode.toLowerCase():null,a=t?'<a href="'+t+'">'+escapeHtml(e.trackLabel)+"</a>":escapeHtml(e.trackLabel),s=CHANGELOG_FIELD_LABELS[e.field]||e.field;return'<div class="card changelog-entry"><div class="changelog-entry-top"><strong>'+a+'</strong><span class="muted">'+new Date(1e3*e.changedAt).toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"})+'</span></div><p class="changelog-entry-change">'+escapeHtml(s)+": "+escapeHtml(changelogValueLabel(e.field,e.oldValue))+" → <strong>"+escapeHtml(changelogValueLabel(e.field,e.newValue))+'</strong></p><p class="muted changelog-entry-reason">'+escapeHtml(e.reason)+"</p></div>"}).join("");appEl.innerHTML='<div class="narrow-page changelog-page"><span class="section-eyebrow">Real, dated corrections</span><h1>Exam Mechanics Changelog</h1><p class="page-intro-text">Every question count, time limit, and passing score on PassExamHQ is sourced from the current official handbook or statute for that state. When we catch a real correction — a source we misread, a bulletin the state updated — it\'s logged here, with the reason, rather than silently edited. '+(t.length?"This log currently covers "+t.length+" correction"+(1===t.length?"":"s")+".":"Nothing has needed correcting yet — this page will show real entries as they happen.")+"</p>"+(a||'<p class="muted">No corrections logged yet.</p>')+"</div>"})}registerDeep({renderTerms:renderTerms,renderPrivacy:renderPrivacy,renderAbout:renderAbout,renderFaq:renderFaq,renderGuarantee:renderGuarantee,renderPassRates:renderPassRates,renderChangelog:renderChangelog,renderContact:renderContact,renderEmbedGenerator:renderEmbedGenerator,renderBlogList:renderBlogList,renderBlogPost:renderBlogPost,drawBlogList:drawBlogList,blogListHref:blogListHref,embedPickerHtml:embedPickerHtml,embedResultHtml:embedResultHtml});